'use strict';
let importMode='replace',dataTab='manual',manualDraft=null,manualMode='append',tutorialIndex=-1;
const exportColumns=[...E.columns,...W.extra];
function optionList(items,current){return items.map(([value,label])=>'<option value="'+esc(value)+'" '+(String(current)===String(value)?'selected':'')+'>'+esc(label)+'</option>').join('');}
function subjectOptions(){return [...new Set([...W.subjects,...state.rows.map(r=>r.subject),state.profile.subject])].map(x=>'<option value="'+esc(x)+'"></option>').join('');}
function contextForm(p,id='context'){return '<form id="'+id+'" class="context-form"><label>Тип учреждения<select name="type" required>'+optionList(Object.entries(W.types).map(([k,v])=>[k,v.label]),p.type)+'</select></label><label>Название учреждения <span class="optional">необязательно</span><input name="name" maxlength="120" value="'+esc(p.name)+'" placeholder="Например, школа № 12"></label><label><span class="level-label">'+(p.type==='school'?'Класс обучения':'Курс обучения')+'</span><select name="level">'+optionList(Array.from({length:W.types[p.type].max},(_,i)=>[i+1,(i+1)+' '+W.types[p.type].unit]),p.level)+'</select></label><label>Предмет<input name="subject" required maxlength="80" list="subjects-list" value="'+esc(p.subject)+'" placeholder="Выберите или напишите свой"></label><datalist id="subjects-list">'+subjectOptions()+'</datalist><div class="context-actions"><button type="submit" class="button primary">Сохранить настройки</button><span class="small-note">Настройки сохраняются в этом браузере</span></div><div class="form-feedback" role="alert"></div></form>';}
function wireContext(form,after){form.elements.type.onchange=()=>{const t=W.types[form.elements.type.value],level=Number(form.elements.level.value);form.querySelector('.level-label').textContent=form.elements.type.value==='school'?'Класс обучения':'Курс обучения';form.elements.level.innerHTML=optionList(Array.from({length:t.max},(_,i)=>[i+1,(i+1)+' '+t.unit]),Math.min(level,t.max));};form.onsubmit=e=>{e.preventDefault();const p=W.profile(Object.fromEntries(new FormData(form)));const errors=W.checkProfile(p);if(errors.length){form.querySelector('.form-feedback').textContent=errors.join('. ');return;}const changed=!W.matches({institution_type:state.profile.type,level:state.profile.level,subject:state.profile.subject},p);state.profile=p;state.configured=true;state.class='all';state.book='all';if(changed){manualDraft=null;state.approved=null;state.importMessage=null;}persist();render();if(after)after();toast('Настройки учреждения и предмета сохранены');};}
function openSettings(first=false){const d=$('#settings-dialog');d.innerHTML='<div class="modal-head"><div class="eyebrow">'+(first?'ДОБРО ПОЖАЛОВАТЬ В EDULENS':'ВАШЕ ОБУЧЕНИЕ')+'</div>'+(!first?'<button class="icon-button" id="settings-close" aria-label="Закрыть настройки">×</button>':'')+'</div><h2>'+(first?'Начнём с вашего учреждения':'Настройки учреждения')+'</h2><p>Укажите, где проходит обучение. Мы подстроим классы, курсы и данные под выбранный предмет.</p>'+contextForm(state.profile,'settings-form');wireContext($('#settings-form'),()=>{d.close();if(first)afterInstitution();});if(!first)$('#settings-close').onclick=()=>d.close();d.oncancel=e=>{if(first)e.preventDefault();};d.showModal();}
function emptyContext(){if(isStudent())return '<section class="panel empty-context"><div class="empty-symbol">◫</div><h2>Диагностических результатов пока нет</h2><p>Учитель может добавить результаты тестирования вашей группы. Оценки журнала доступны в отдельном разделе.</p><button class="button primary" data-page="journal">Открыть мой журнал →</button></section>';return'<section class="panel empty-context"><div class="empty-symbol">◫</div><span class="eyebrow">ВАША УЧЕБНАЯ СРЕДА</span><h2>Здесь появятся ваши результаты</h2><p>'+esc(W.caption(state.profile))+'</p><p class="small-note">Добавьте ответы вручную или загрузите CSV. Данные других предметов и уровней сохранены отдельно.</p><button class="button primary" data-page="data">Добавить данные →</button></section>';}
function blankRow(){return{student_id:'',class:state.profile.type==='school'?state.profile.level+'А':'Группа 1',topic:'',question_id:'Q1',textbook:'Материал 1',phase:'post',score:'',max_score:10,hours:4};}
function manualEditor(){if(!manualDraft)manualDraft=[blankRow()];return'<div class="callout compact"><b>'+esc(W.caption(state.profile))+'</b><br>Одна строка — ответ на одно задание. Для сравнения «до / после» добавьте две строки с одинаковым ID обучающегося и разными этапами.</div><div class="editor-actions"><label>При сохранении <select id="manual-mode">'+optionList([['append','Добавить к текущим данным'],['replace','Заменить данные этого предмета и уровня']],manualMode)+'</select></label><button class="button" id="edit-existing" '+(!contextRows().length?'disabled':'')+'>Редактировать текущие данные</button></div><div class="table-wrap manual-table"><table><thead><tr>'+['ID обучающегося','Класс / группа','Тема','ID задания','Учебник / материал','Этап','Балл','Максимум','Часы темы',''].map(x=>'<th>'+x+'</th>').join('')+'</tr></thead><tbody id="manual-rows">'+manualDraft.map((r,i)=>manualRow(r,i)).join('')+'</tbody></table></div><div class="editor-actions"><button class="button" id="add-row">＋ Добавить ответ</button><span class="small-note">До 200 ответов вручную. Для больших наборов используйте CSV.</span></div><div id="manual-feedback" role="alert"></div><div class="editor-footer"><button class="button primary" id="save-manual">Сохранить и пересчитать</button><span class="small-note">Другие предметы и уровни не изменятся</span></div>';}
function manualRow(r,i){const names={student_id:'ID обучающегося',class:'Класс или группа',topic:'Тема',question_id:'ID задания',textbook:'Учебник или материал',phase:'Этап',score:'Балл',max_score:'Максимум',hours:'Часы темы'};return'<tr data-row="'+i+'">'+E.columns.map(k=>'<td>'+(k==='phase'?'<select aria-label="Этап '+(i+1)+'" data-key="phase">'+optionList([['pre','До обучения'],['post','После обучения']],r[k])+'</select>':'<input aria-label="'+names[k]+' '+(i+1)+'" data-key="'+k+'" '+(['score','max_score','hours'].includes(k)?'type="number" min="'+(k==='score'?0:1)+'" step="'+(k==='hours'?'1':'any')+'"':'type="text" maxlength="160"')+' value="'+esc(r[k])+'" placeholder="'+({student_id:'S001',topic:'Название темы',score:'0'}[k]||'')+'">')+'</td>').join('')+'<td><button class="delete-row" data-remove="'+i+'" aria-label="Удалить ответ '+(i+1)+'">×</button></td></tr>';}
function fileEditor(){return'<div class="callout compact"><b>'+esc(W.caption(state.profile))+'</b><br>Файл без столбцов предмета и уровня будет привязан к выбранным настройкам. Расширенный CSV должен совпадать с ними.</div><div class="editor-actions"><label>При загрузке <select id="import-mode">'+optionList([['replace','Заменить данные этого предмета и уровня'],['append','Добавить к текущим данным']],importMode)+'</select></label></div><div class="upload-area" id="dropzone"><span class="upload-icon">⇧</span><h3>Загрузите результаты из файла</h3><p>Перетащите CSV или выберите файл.<br>До 10 МБ, UTF-8, до 100 000 ответов в рабочем пространстве.</p><input type="file" id="csv-file" accept=".csv,text/csv" aria-label="Загрузить CSV"></div><div id="import-feedback" role="alert">'+(state.importMessage?'<div class="'+(state.importMessage.error?'error-list':'success-box')+'">'+esc(state.importMessage.text)+'</div>':'')+'</div><div class="editor-footer"><button class="button" id="template">↓ Скачать шаблон CSV</button><span class="small-note">XLSX: сохраните таблицу как CSV перед загрузкой</span></div>';}
function workspaceDataPage(){const rs=contextRows();return panel('Ваша учебная среда','Учреждение, уровень и предмет определяют текущую выборку','<div class="panel-body">'+contextForm(state.profile,'data-context')+'</div>','<button class="text-link" id="data-tutorial">Пройти туториал ↗</button>')+'<div class="section-gap">'+panel('Добавьте учебные результаты','Вручную или из файла — оба способа используют одну проверку данных','<div class="entry-tabs" role="tablist" aria-label="Способ ввода"><button role="tab" aria-selected="'+(dataTab==='manual')+'" class="'+(dataTab==='manual'?'selected':'')+'" id="tab-manual">⌨ Вручную</button><button role="tab" aria-selected="'+(dataTab==='file')+'" class="'+(dataTab==='file'?'selected':'')+'" id="tab-file">⇧ Из файла CSV</button></div><div class="panel-body" role="tabpanel" aria-labelledby="tab-'+dataTab+'">'+(dataTab==='manual'?manualEditor():fileEditor())+'</div>')+'</div><div class="data-layout section-gap">'+panel('Текущая выборка',esc(W.caption(state.profile)),'<div class="panel-body"><div class="hour-line"><span>Ответов / обучающихся</span><b>'+rs.length+' / '+new Set(rs.map(r=>r.student_id)).size+'</b></div><div class="hour-line"><span>Тем / групп / материалов</span><b>'+[new Set(rs.map(r=>r.topic)).size,new Set(rs.map(r=>r.class)).size,new Set(rs.map(r=>r.textbook)).size].join(' / ')+'</b></div><p class="small-note">Всего в рабочем пространстве: '+state.rows.length+' ответов. Фильтры группы и учебника не ограничивают редактирование выбранного предмета и уровня.</p><button class="button" id="download-data" '+(!rs.length?'disabled':'')+'>↓ Скачать выбранные данные</button></div>')+panel('Попробуйте без своих данных','Отдельный демонстрационный пример','<div class="panel-body"><p class="small-note">Математика, школа, 7 класс: 120 обучающихся и 6 тем. При добавлении сохраняются ваши данные. Демо использует отдельные ID и группы.</p><button class="button" id="demo-reset">Открыть демопример</button><p class="small-note">Для нового предмета сначала укажите его в настройках выше, затем добавьте собственные темы и ответы.</p></div>')+'</div><div class="section-gap">'+panel('Памятка по данным','Что нужно для корректной аналитики','<div class="panel-body"><div class="guide-step"><b>Баллы и отсутствие</b><p>0 — неверный или пропущенный ответ в сданном тесте. Отсутствующего на тесте не добавляйте с нулём.</p></div><div class="guide-step"><b>Сопоставимость</b><p>Используйте одинаковые ID для сопоставимых заданий и одинаковые комплекты заданий. Плановые часы по одной теме должны совпадать.</p></div><div class="guide-step"><b>Формат CSV</b><p>'+E.columns.map(k=>'<code class="mono">'+k+'</code>').join(' ')+'</p><p>Дополнительно: <code>institution_type</code> (school / college / university), <code>level</code> (номер класса или курса), <code>subject</code> (название предмета). Если указаны, они должны совпадать с настройками. Этап: pre или post. Разделитель: запятая или точка с запятой.</p></div><p class="small-note">Данные хранятся в этом браузере. Перед сменой устройства скачайте CSV. Для смены учебного года сохраните предыдущий набор отдельно и загрузите новый.</p></div>')+'</div>';}
function saveDataset(incoming,mode,label){if(!isTeacher())return{errors:['Только в кабинете учителя']};const prepared=W.prepareImport(incoming,state.profile);if(prepared.errors.length)return prepared;const merged=W.merge(state.rows,prepared.rows,state.profile,mode);const v=E.validate(merged);if(v.errors.length)return v;state.rows=v.rows;state.source='workspace';state.file=label;state.class='all';state.book='all';state.approved=null;persist();return v;}
function readManual(){manualDraft=[...document.querySelectorAll('#manual-rows tr')].map(tr=>Object.fromEntries([...tr.querySelectorAll('[data-key]')].map(el=>[el.dataset.key,el.value.trim()])));return manualDraft;}
function bindSetup(){if(page!=='data')return;wireContext($('#data-context'));$('#data-tutorial').onclick=startTutorial;$('#tab-manual').onclick=()=>{dataTab='manual';render();};$('#tab-file').onclick=()=>{if($('#manual-rows'))readManual();dataTab='file';render();};$('#download-data').onclick=()=>download('edulens-data.csv',E.csv(contextRows(),exportColumns));$('#demo-reset').onclick=()=>{const demo=W.stamp(E.demo().map(r=>({...r,student_id:'DEMO-'+r.student_id,class:'Демо '+r.class,demo:true})),W.defaults);state.rows=[...state.rows.filter(r=>!r.demo),...demo];state.profile={...W.defaults,name:state.profile.type==='school'?state.profile.name:''};state.class='all';state.book='all';state.approved=null;manualDraft=null;persist();render();navigate('overview');toast('Открыт синтетический пример. Ваши данные сохранены.');};if(dataTab==='manual'){
$('#manual-mode').onchange=e=>manualMode=e.target.value;
document.querySelectorAll('#manual-rows input,#manual-rows select').forEach(el=>{el.oninput=readManual;el.onchange=readManual;});
document.querySelectorAll('[data-remove]').forEach(el=>el.onclick=()=>{readManual();manualDraft.splice(Number(el.dataset.remove),1);if(!manualDraft.length)manualDraft=[blankRow()];render();});
$('#add-row').onclick=()=>{readManual();if(manualDraft.length>=200){toast('Для более 200 ответов используйте CSV');return;}const prev=manualDraft[manualDraft.length-1];manualDraft.push({...blankRow(),class:prev.class,topic:prev.topic,textbook:prev.textbook,hours:prev.hours,max_score:prev.max_score,question_id:prev.question_id,phase:prev.phase});render();};
$('#edit-existing').onclick=()=>{if(contextRows().length>200){toast('В наборе более 200 ответов. Скачайте CSV и отредактируйте файл.');return;}manualDraft=contextRows().map(r=>({...r}));manualMode='replace';render();toast('Загружены ответы выбранного предмета и уровня');};
$('#save-manual').onclick=()=>{const draft=readManual(),checked=E.validate(W.stamp(draft,state.profile));if(checked.errors.length){$('#manual-feedback').innerHTML='<div class="error-list">'+esc(checked.errors.slice(0,8).map(e=>e.replace(/Строка (\d+)/,(_,n)=>'Ответ '+(Number(n)-1))).join('\n'))+'</div>';return;}const result=saveDataset(checked.rows,manualMode,'Ручной ввод');if(result.errors.length){$('#manual-feedback').innerHTML='<div class="error-list">'+esc(result.errors.slice(0,8).join('\n'))+'</div>';return;}manualDraft=null;render();$('#manual-feedback').innerHTML='<div class="success-box">Сохранено '+draft.length+' ответов. Аналитика пересчитана. <button class="text-link" id="see-results">Открыть обзор →</button></div>';$('#see-results').onclick=()=>navigate('overview');toast('Результаты сохранены');};
}else{$('#import-mode').onchange=e=>importMode=e.target.value;$('#csv-file').onchange=e=>importFile(e.target.files[0]);$('#dropzone').ondragover=e=>e.preventDefault();$('#dropzone').ondrop=e=>{e.preventDefault();importFile(e.dataTransfer.files[0]);};$('#template').onclick=()=>download('edulens-template.csv',E.csv(W.stamp([{student_id:'S001',class:state.profile.type==='school'?state.profile.level+'А':'Группа 1',topic:'Первая тема',question_id:'Q1',textbook:'Материал 1',phase:'pre',score:2,max_score:5,hours:4},{student_id:'S001',class:state.profile.type==='school'?state.profile.level+'А':'Группа 1',topic:'Первая тема',question_id:'Q1',textbook:'Материал 1',phase:'post',score:4,max_score:5,hours:4}],state.profile),exportColumns));}}
const tutorialSteps=[{page:'data',title:'Ваша учебная среда',text:'Начните с типа учреждения, класса или курса и предмета. Школа: 1–11 классы, колледж: 1–3 курса, университет: 1–4 курса. Можно добавить свой предмет.',target:'#data-context',icon:'⌂'},{page:'data',title:'Два способа добавить результаты',text:'В разделе «Вручную» внесите ID, тему, задание и баллы. Кнопка «Добавить ответ» создаёт новую строку. Во вкладке «Из файла CSV» есть шаблон. Выберите добавление или замену данных.',target:'.entry-tabs',icon:'⇧'},{page:'overview',title:'Обзор и фильтры',text:'Верхние фильтры переключают уровень, предмет, группу и учебник. Все показатели пересчитываются. Если данных пока нет, добавьте их в разделе «Данные» или откройте демопример.',target:'.toolbar',icon:'▦'},{page:'topics',title:'Разберите сложную тему',text:'Откройте карточку темы: увидите баллы по заданиям и долю обучающихся ниже цели. Малые и неполные выборки отмечаются отдельно.',target:'#content',icon:'◫'},{page:'books',title:'Сравните учебные материалы',text:'Смотрите на результаты до и после обучения и объём выборки. Наблюдаемая разница не доказывает, что её причина — учебник.',target:'#content',icon:'▤'},{page:'plan',title:'Проверьте учебный план',text:'Задайте цель, минимум часов и предел переноса. Система сохранит общий объём. Проверьте предложение, утвердите его и скачайте CSV. Туториал можно повторить кнопкой «Как это работает».',target:'#content',icon:'◷'}];
function startTutorial(){if($('#settings-dialog').open)$('#settings-dialog').close();tutorialIndex=0;showTutorial();}
function showTutorial(){const steps=activeTutorial();const step=steps[tutorialIndex];if(!step)return;document.querySelectorAll('.tour-highlight').forEach(el=>el.classList.remove('tour-highlight'));page=step.page;history.replaceState(null,'','#'+step.page);render();window.scrollTo(0,0);const target=$(step.target);if(target)target.classList.add('tour-highlight');const box=$('#tutorial');box.hidden=false;box.innerHTML='<div class="tour-top"><span>ЗНАКОМСТВО С EDULENS</span><button class="icon-button" id="tour-close" aria-label="Закрыть туториал">×</button></div><div class="tour-progress">'+steps.map((_,i)=>'<span class="'+(i<=tutorialIndex?'filled':'')+'"></span>').join('')+'</div><span class="tour-icon">'+step.icon+'</span><div class="eyebrow">ШАГ '+(tutorialIndex+1)+' ИЗ '+steps.length+'</div><h2 id="tour-title">'+step.title+'</h2><p>'+step.text+'</p><div class="tour-controls"><button class="text-link" id="tour-skip">Пропустить</button><div><button class="button" id="tour-back" '+(tutorialIndex===0?'disabled':'')+'>Назад</button> <button class="button primary" id="tour-next">'+(tutorialIndex===steps.length-1?'Готово ✓':'Далее →')+'</button></div></div>';$('#tour-close').onclick=finishTutorial;$('#tour-skip').onclick=finishTutorial;$('#tour-back').onclick=()=>{tutorialIndex--;showTutorial();};$('#tour-next').onclick=()=>{if(tutorialIndex===steps.length-1)finishTutorial();else{tutorialIndex++;showTutorial();}};}
function finishTutorial(){state.tutorialDone=true;persist();tutorialIndex=-1;$('#tutorial').hidden=true;document.querySelectorAll('.tour-highlight').forEach(el=>el.classList.remove('tour-highlight'));toast('Туториал доступен в меню «Как это работает»');}
const settings=document.createElement('dialog');settings.id='settings-dialog';document.body.append(settings);const tour=document.createElement('section');tour.id='tutorial';tour.className='tutorial';tour.hidden=true;tour.setAttribute('role','region');tour.setAttribute('aria-label','Пошаговый туториал');tour.setAttribute('aria-live','polite');document.body.append(tour);
$('#workspace-settings').onclick=()=>openSettings();$('#level-filter').onchange=e=>{state.profile.level=Number(e.target.value);state.class='all';state.book='all';manualDraft=null;persist();render();};$('#subject-filter').onchange=e=>{state.profile.subject=e.target.value;state.class='all';state.book='all';manualDraft=null;persist();render();};
state.rows=state.rows.map(r=>({...r,demo:r.demo===true||(state.source==='demo'&&W.matches(r,W.defaults))}));

